// HasDocs applies the HasEdge predicate on the "docs" edge.
func HasDocs() predicate.AiKnowledgeBase {
	return predicate.AiKnowledgeBase(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, DocsTable, DocsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDocsWith applies the HasEdge predicate on the "docs" edge with a given conditions (other predicates).
func HasDocsWith(preds ...predicate.AiDoc) predicate.AiKnowledgeBase {
	return predicate.AiKnowledgeBase(func(s *sql.Selector) {
		step := newDocsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AiKnowledgeBase) predicate.AiKnowledgeBase {
	return predicate.AiKnowledgeBase(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AiKnowledgeBase) predicate.AiKnowledgeBase {
	return predicate.AiKnowledgeBase(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AiKnowledgeBase) predicate.AiKnowledgeBase {
	return predicate.AiKnowledgeBase(sql.NotPredicates(p))
}
